sys_ws_operation.operation_script:
// RBAC Authorization Check
var __authorized = (function() {
  if (gs.hasRole("admin")) return true;
  var roles = "x_2056099_indust_0.production_planner,x_2056099_indust_0.production_manager,x_2056099_indust_0.plant_manager,x_2056099_indust_0.operations_manager".split(",");
  for (var _i = 0; _i < roles.length; _i++) {
    if (gs.hasRole(roles[_i])) return true;
  }
  response.setStatus(403);
  response.setBody({error:"Unauthorized",message:"Insufficient role for this operation"});
  return false;
})();
if (!__authorized) { /* early exit */ }
else
(function process(request, response) {
  // API execution flag for lifecycle guard BR
  gs.getSession().putClientData("x_2056099_indust_0_api_transition", "confirm");

  var SCHED_TABLE = "x_2056099_indust_0_prod_sched";
  var body = {};
  try { body = JSON.parse(request.body.dataString); } catch (e) {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "Invalid request body" } });
    return;
  }
  var schedId = body.schedule_id;
  if (!schedId) {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "schedule_id is required" } });
    return;
  }
  var gr = new GlideRecord(SCHED_TABLE);
  if (!gr.get(schedId)) {
    response.setStatus(404);
    response.setBody({ result: { success: false, error: "Production Schedule not found" } });
    return;
  }
  var currentStatus = gr.getValue("status");

  // TRANSITION 1: draft -> scheduled (planner scheduling)
  if (currentStatus == "draft") {
    // Any role in the RBAC check can schedule a draft
    gr.setValue("status", "scheduled");
    gr.update();
    response.setBody({
      result: {
        success: true,
        message: "Schedule moved to Scheduled status. Awaiting manager approval to Confirmed.",
        schedule_id: schedId,
        previous_status: "draft",
        new_status: "scheduled"
      }
    });
    return;
  }

  // TRANSITION 2: scheduled -> confirmed (manager approval)
  if (currentStatus == "scheduled") {
    // Only manager-level roles can approve (confirm)
    var isManager = gs.hasRole("admin") ||
                    gs.hasRole("x_2056099_indust_0.production_manager") ||
                    gs.hasRole("x_2056099_indust_0.plant_manager") ||
                    gs.hasRole("x_2056099_indust_0.operations_manager");
    if (!isManager) {
      response.setStatus(403);
      response.setBody({
        result: {
          success: false,
          error: "Only production_manager, plant_manager, or operations_manager can approve (confirm) a scheduled production schedule. production_planner cannot self-approve."
        }
      });
      return;
    }
    gr.setValue("status", "confirmed");
    gr.setValue("confirmed_by", gs.getUserID());
    gr.setValue("confirmation_date", new GlideDateTime().getValue());
    gr.update();
    response.setBody({
      result: {
        success: true,
        message: "Schedule approved and confirmed by manager. Ready for production execution.",
        schedule_id: schedId,
        previous_status: "scheduled",
        new_status: "confirmed",
        confirmed_by: gs.getUserID(),
        confirmation_date: new GlideDateTime().getDisplayValue()
      }
    });
    return;
  }

  // All other statuses are invalid for confirmation
  var errorMsg = "Cannot confirm schedule. Current status: " + gr.getDisplayValue("status") + ". ";
  if (currentStatus == "confirmed") errorMsg += "Schedule is already confirmed.";
  else if (currentStatus == "in_progress") errorMsg += "Schedule is already in progress.";
  else if (currentStatus == "completed") errorMsg += "Cannot confirm a completed schedule.";
  else if (currentStatus == "cancelled") errorMsg += "Cannot confirm a cancelled schedule.";
  else errorMsg += "Only draft or scheduled schedules can be progressed.";
  response.setStatus(400);
  response.setBody({ result: { success: false, error: errorMsg } });
})(request, response);
